{"files":[{"path":"src/lib.rs","contents":"use std::os::raw::c_int;

#[unsafe(no_mangle)]
pub extern "C" fn encode_quant(
    uni: c_int,
    step: c_int,
    pred: c_int,
    tgt: c_int,
    tgt2: c_int,
    lsbit: c_int,
) -> c_int {
    let mut uni = uni;
    let mut uni1 = uni + 1;
    let mut uni2 = uni - 1;
    let mut diff;
    let p0;
    let p1;
    let p2;
    let d3;
    let mut d0;
    let mut d1;
    let mut d2;

    if ((uni ^ uni1) & !7) != 0 {
        uni1 = uni;
    }
    if ((uni ^ uni2) & !7) != 0 {
        uni2 = uni;
    }

    if lsbit != 0 {
        if lsbit == 4 {
            uni &= !1;
            uni1 &= !1;
            uni2 &= !1;
            uni |= (uni >> 1) & (uni >> 2) & 1;
            uni1 |= (uni1 >> 1) & (uni1 >> 2) & 1;
            uni2 |= (uni2 >> 1) & (uni2 >> 2) & 1;
        } else if (lsbit & 1) != 0 {
            uni |= 1;
            uni1 |= 1;
            uni2 |= 1;
        } else {
            uni &= !1;
            uni1 &= !1;
            uni2 &= !1;
        }
    }

    diff = ((2 * (uni & 7) + 1) * step) / 8;
    if (uni & 8) != 0 {
        diff = -diff;
    }
    p0 = pred + diff;
    d0 = tgt - p0;
    d0 ^= d0 >> 31;

    diff = ((2 * (uni1 & 7) + 1) * step) / 8;
    if (uni1 & 8) != 0 {
        diff = -diff;
    }
    p1 = pred + diff;
    d1 = tgt - p1;
    d1 ^= d1 >> 31;

    diff = ((2 * (uni2 & 7) + 1) * step) / 8;
    if (uni2 & 8) != 0 {
        diff = -diff;
    }
    p2 = pred + diff;
    d2 = tgt - p2;
    d2 ^= d2 >> 31;

    let mut d3v = tgt2 - p0;
    d3v ^= d3v >> 31;
    d0 += d3v >> 5;

    d3v = tgt2 - p1;
    d3v ^= d3v >> 31;
    d1 += d3v >> 5;

    d3v = tgt2 - p2;
    d3v ^= d3v >> 31;
    d2 += d3v >> 5;

    if d1 < d0 {
        uni = uni1;
    }
    if d2 < d0 {
        uni = uni2;
    }

    uni
}
